/**
 * Ambient type declaration for the Pagefind JS API runtime bundle.
 *
 * `/pagefind/pagefind.js` is a postbuild artifact (generated by
 * `pagefind --site out --force-language ko`). It does not exist at
 * typecheck time, so TypeScript cannot resolve it from `node_modules`.
 * This declaration gives the dynamic import a typed surface without
 * requiring the binary to be present during CI typecheck.
 *
 * Docs: https://pagefind.app/docs/api/
 */

declare module "/pagefind/pagefind.js" {
  export interface PagefindSearchOptions {
    filters?: Record<string, string | Record<string, string | string[]>>;
    sort?: Record<string, "asc" | "desc">;
  }

  export interface PagefindResultData {
    url: string;
    excerpt: string;
    meta: Record<string, string>;
    filters: Record<string, string[]>;
  }

  export interface PagefindResult {
    data: () => Promise<PagefindResultData>;
  }

  export interface PagefindSearchResponse {
    results: PagefindResult[];
  }

  export function search(
    query: string | null,
    options?: PagefindSearchOptions,
  ): Promise<PagefindSearchResponse>;

  export function init(): Promise<void>;

  export function filters(): Promise<Record<string, Record<string, number>>>;
}
